animationRules:
@keyframes pzb { 
  0%, 100% { transform: scale(0.8); opacity: 0.75; }
  50% { transform: scale(1.25); opacity: 1; }
}

@keyframes pzr { 
  0% { width: 6px; height: 6px; opacity: 0.9; }
  60%, 100% { width: 30px; height: 30px; opacity: 0; }
}

@keyframes ring { 
  0% { width: 6px; height: 6px; opacity: 0.9; }
  35% { width: 80px; height: 80px; opacity: 0; }
  100% { width: 80px; height: 80px; opacity: 0; }
}

@keyframes halo { 
  0%, 100% { transform: scale(0.8); opacity: 0.6; }
  50% { transform: scale(1.15); opacity: 1; }
}

@keyframes rip { 
  0% { transform: scale(1); opacity: 0.9; }
  100% { transform: scale(3.6); opacity: 0; }
}

@keyframes rise { 
  0% { opacity: 0; transform: translateY(16px); }
  100% { opacity: 1; transform: none; }
}

@keyframes cntpop { 
  0% { opacity: 0; scale: 0.35; }
  55% { opacity: 1; scale: 1.22; }
  100% { opacity: 1; scale: 1; }
}

@keyframes gmote { 
  0% { opacity: 0; transform: translate(0px, 0px); }
  18% { opacity: var(--mo,.8); }
  50% { transform: translate(calc(var(--dx)*.55),calc(var(--dy)*.5)); }
  82% { opacity: var(--mo,.8); }
  100% { opacity: 0; transform: translate(var(--dx),var(--dy)); }
}

@keyframes phring { 
  0% { transform: translate(-50%, -50%) scale(0.075); opacity: 0.9; }
  35%, 100% { transform: translate(-50%, -50%) scale(1); opacity: 0; }
}

@keyframes phpzr { 
  0% { transform: translate(-50%, -50%) scale(0.2); opacity: 0.9; }
  60%, 100% { transform: translate(-50%, -50%) scale(1); opacity: 0; }
}

@keyframes phspecs { 
  0% { transform: translateX(0px) skewX(-18deg); }
  14%, 100% { transform: translateX(780px) skewX(-18deg); }
}
